const C=Core,KEY='ruang-kelas-kosong-v2',RECOVERY=KEY+'-before-restore';
let db,storageError='';
try{const raw=localStorage.getItem(KEY);db=raw?C.validate(JSON.parse(raw)):C.blank()}catch(e){db=C.blank();storageError='Data tersimpan tidak dapat dibaca. Salinan lama tetap dipertahankan. Gunakan Cadangan & data untuk mengunduh data mentah atau memulihkan JSON.'}
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uid=prefix=>prefix+(crypto.randomUUID?crypto.randomUUID():Date.now().toString(36)+Math.random().toString(36).slice(2));
const today=()=>{const p=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Makassar',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date());return ['year','month','day'].map(k=>p.find(x=>x.type===k).value).join('-')};
const niceDate=(v,short=false)=>v?new Date(v+'T12:00:00').toLocaleDateString('id-ID',{day:'numeric',month:short?'short':'long',year:'numeric'}):'Tanggal belum ditetapkan';
const num=v=>v===null||v===undefined?'—':v.toLocaleString('id-ID',{maximumFractionDigits:1});
const subject=id=>db.subjects.find(s=>s.id===id)?.name||'Mata pelajaran';
const initials=s=>s.split(' ').filter(Boolean).slice(0,2).map(x=>x[0]).join('');
let page='dashboard',attDate=today(),attMonth=today().slice(0,7),attChartPeriod='month',gradeSubject=db.subjects[0]?.id||'',gradeType='sumative',gradeScope='current',reportStudent='',search='',journalMonth='',toastTimer;
const navs=[['school','Data sekolah','M3 21V7l9-4 9 4v14M7 10h2m6 0h2M7 14h2m6 0h2M10 21v-4h4v4'],['class','Data kelas','M3 3h18v14H3ZM8 21h8m-4-4v4'],['subjects','Mata pelajaran','M4 3h16v18H4ZM8 7h8M8 11h8M8 15h8'],['dashboard','Ringkasan','M3 10 12 3l9 7v11h-6v-7H9v7H3Z'],['students','Data murid','M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M9 3a4 4 0 1 0 0 8 4 4 0 0 0 0-8M20 21v-2a4 4 0 0 0-3-3.87M16 3a4 4 0 0 1 0 8'],['attendance','Daftar hadir','M8 2v4m8-4v4M3 10h18M5 4h14a2 2 0 0 1 2 2v14H3V6a2 2 0 0 1 2-2m3 11 3 3 5-5'],['grades','Asesmen & nilai','M4 3h16v18H4ZM8 7h8M8 11h8M8 15h3m4 0h1'],['analysis','Analisis soal','M4 3h16v18H4ZM8 16v-4m4 4V8m4 8v-6'],['competency','Sikap & kedisiplinan','M12 3 3 7v6c0 5 9 8 9 8s9-3 9-8V7Zm-4 9 3 3 5-5'],['journal','Jurnal mengajar','M3 3h6a4 4 0 0 1 3 2 4 4 0 0 1 3-2h6v17h-6a4 4 0 0 0-3 1 4 4 0 0 0-3-1H3ZM12 5v16'],['extracurricular','Ekstrakurikuler','M4 4h16v16H4ZM8 8h8M8 12h8M8 16h4'],['reports','Pengolahan rapor','M6 3h12v18l-6-3-6 3ZM9 7h6M9 11h6'],['backup','Cadangan & data','M12 3v12m-4-4 4 4 4-4M4 15v6h16v-6'],['settings','Pengaturan','M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8M9 2h6l1 4 4 1 2 5-3 3-1 5h-6l-3-3-4-1-2-5 3-3Z']];
navs.unshift(navs.splice(navs.findIndex(n=>n[0]==='dashboard'),1)[0]);
const btn=(action,text,cls='',attrs='')=>`<button data-action="${action}" class="${cls}" ${attrs}>${text}</button>`;
const empty=(title,text,action='')=>`<div class="empty"><div style="font-size:28px;color:#a4b395">✧</div><h3>${title}</h3><p>${text}</p>${action}</div>`;
const input=(label,name,value='',type='text',extra='')=>`<label class="field">${label}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;
const textarea=(label,name,value='',extra='')=>`<label class="field full">${label}<textarea name="${name}" ${extra}>${esc(value)}</textarea></label>`;
const opts=(items,value)=>items.map(([v,l])=>`<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(l)}</option>`).join('');
const sel=(label,name,items,value,extra='')=>`<label class="field">${label}<select name="${name}" ${extra}>${opts(items,value)}</select></label>`;
const subOpts=()=>db.subjects.map(s=>[s.id,s.name]);
const head=(title,subtitle,buttons='')=>`<div class="page-head"><div><div class="eyebrow">${esc(db.settings.className?'Kelas '+db.settings.className:'Kelas belum diisi')} · ${esc(db.settings.school||'Sekolah belum diisi')}</div><h1>${title}</h1><div class="sub">${subtitle}</div></div><div class="actions no-print">${buttons}</div></div>`;
const nameCell=s=>`<span class="student-name"><span class="avatar">${esc(initials(s.name))}</span><span>${esc(s.name)}<small>NIS ${esc(s.nis||'belum diisi')}</small></span></span>`;
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4200)}
function commit(next){try{if(storageError)throw Error(storageError);C.validate(next);localStorage.setItem(KEY,JSON.stringify(next));db=next;$('#save-status').textContent='✓ Tersimpan di perangkat';return true}catch(e){toast('Belum tersimpan: '+e.message);$('#save-status').textContent='Gagal menyimpan — unduh cadangan';return false}}
function mutate(fn){const next=structuredClone(db);fn(next);return commit(next)}
function download(name,text,type='application/json'){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),5000)}
function backup(){download(DocumentNames.make(db,'Cadangan Data Ruang Kelas','json',{date:today()}),JSON.stringify({...db,exportedAt:new Date().toISOString()},null,2));toast('Cadangan JSON diunduh.')}
function csv(name,rows){download(name,'\ufeff'+rows.map(r=>r.map(v=>'"'+String(v??'').replace(/^[=+@-]/,"' $&").replace(/"/g,'""')+'"').join(';')).join('\r\n'),'text/csv;charset=utf-8')}
function modal(title,content,onSubmit){$('#dialog-body').innerHTML=`<div class="dialog-head"><h2>${title}</h2><button data-action="close" aria-label="Tutup">×</button></div>${content}`;$('#dialog').showModal();const form=$('#dialog form');if(form&&onSubmit)form.addEventListener('submit',e=>{e.preventDefault();onSubmit(new FormData(form),form,e.submitter)})}
function close(){if($('#dialog').open)$('#dialog').close()}
function render(){
 const selected=navs.find(n=>n[0]===page)||navs[0];$('#nav').innerHTML=navs.map(([id,label,path],i)=>`<a href="#${id}" class="${page===id?'active ':''}${id==='backup'?'nav-gap':''}"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="${path}"/></svg>${label}</a>`).join('');$('#crumb').textContent=selected[1];$('#period-pill').textContent=`${db.settings.year} · Semester ${db.settings.semester}`;$('#profile-name').innerHTML=`${esc(db.settings.teacher||'Guru kelas')}<small>${esc(db.settings.className?'Wali kelas '+db.settings.className:'Data kelas belum diisi')}</small>`;
 $('#profile-avatar').textContent=initials(db.settings.teacher)||'RK';
 const views={school:schoolPage,class:classPage,subjects:subjectsPage,dashboard,students,attendance,grades,analysis:analysisPage,competency:competencyPage,journal,extracurricular:extracurricularPage,reports,backup:backupPage,settings};$('#main').innerHTML=(storageError?`<div class="notice">${esc(storageError)}</div>`:'')+views[page]();bindPage();
}
function dashboard(){
 const st=C.active(db),at=C.attendance(db),ja=db.journals.filter(j=>j.period===C.period(db)),as=db.assessments.filter(a=>a.period===C.period(db)),pending=db.assessments.filter(a=>a.period==='review');
 const months=Array.from({length:6},(_,i)=>{const t=new Date(db.settings.start+'T12:00:00');t.setMonth(t.getMonth()+i,1);return `${t.getFullYear()}-${String(t.getMonth()+1).padStart(2,'0')}`});
 const counts=months.map(m=>C.attendance(db,null,m+'-01',m+'-31'));
 const greetings=`Selamat datang, ${esc(db.settings.teacher.split(',')[0]||'Bapak/Ibu Guru')}.`;
 return head('Setiap murid, dalam perhatian.',`${niceDate(today())} · Mari siapkan pembelajaran hari ini.`,btn('go-attendance','＋ Isi presensi','primary'))+
 `<div class="hero"><div><div class="eyebrow">${st.length?'RUANG KERJA GURU':'SELAMAT DATANG DI RUANG KELAS'}</div><h2>${greetings}</h2><p>${st.length?'Data kelas sudah terhubung. Pantau kehadiran, catat proses belajar, dan siapkan laporan perkembangan murid.':'Mulai dari data sekolah, data kelas, dan mata pelajaran. Setelah itu tambahkan murid atau impor melalui template Excel.'}</p>${btn(st.length?'new-journal':'go-school',st.length?'Tulis jurnal hari ini ↗':'Isi data sekolah →','primary small')}</div><div class="hero-art" aria-hidden="true"><span class="art-star">✦</span><div class="book"></div><span class="art-dot"></span></div></div>`+
 `<div class="stats">${[[st.length,'Murid aktif',`${st.filter(s=>s.gender==='L').length} laki-laki · ${st.filter(s=>s.gender==='P').length} perempuan`,'♧'],[at.percent===null?'—':num(at.percent)+'%','Kehadiran semester',`${at.total.toLocaleString('id-ID')} presensi tercatat`,'✓'],[as.length,'Asesmen aktif',pending.length?`${pending.length} asesmen impor perlu ditinjau`:'Formatif dan sumatif','▤'],[ja.length,'Jurnal mengajar',`${ja.reduce((a,b)=>a+b.jp,0)} jam pelajaran tercatat`,'▧']].map(([v,l,s,i])=>`<div class="stat"><div class="stat-top">${l}<span class="stat-icon">${i}</span></div><div class="stat-value">${v}</div><small>${s}</small></div>`).join('')}</div>`+
 `<div class="grid-2"><section class="panel" style="margin-bottom:0"><div class="panel-head"><h2>Ritme kehadiran kelas</h2><span class="pill">Semester ${db.settings.semester}</span></div><div class="panel-body"><div class="bars">${counts.map(c=>`<div class="bar-col"><span class="bar-value">${c.percent===null?'Belum ada':num(c.percent)+'%'}</span><div class="bar" style="height:${c.percent===null?2:c.percent*1.05}px"></div></div>`).join('')}</div><div class="bar-labels">${months.map(m=>`<span>${new Date(m+'-01T12:00:00').toLocaleDateString('id-ID',{month:'short'})}</span>`).join('')}</div><div class="chart-foot">Persentase hadir dari seluruh status yang telah dicatat. Tanggal kosong belum dihitung.</div></div></section><section class="panel" style="margin-bottom:0"><div class="panel-head"><h2>Mulai dari sini</h2><span class="tag">AKSES CEPAT</span></div><div class="panel-body">${[['attendance','✓','Catat kehadiran','Satu tanggal, seluruh murid.'],['grades','▤','Kelola asesmen','Nilai per tujuan pembelajaran.'],['reports','▧','Siapkan rapor','Rekap nilai dan catatan perkembangan.']].map(([id,i,t,s])=>`<a class="quick-row" href="#${id}"><span class="quick-icon">${i}</span><span><b>${t}</b><p>${s}</p></span><span class="arrow">↗</span></a>`).join('')}</div></section></div>`+
 (pending.length?`<div class="notice">${pending.length} asesmen dari Excel menunggu penetapan periode. Label tahun sumber berbeda dengan periode aktif. <a href="#backup"><b>Tinjau data impor →</b></a></div>`:'')+
 `<section class="panel"><div class="panel-head"><div><h2>Murid & perkembangan</h2><small>Ringkasan berdasarkan data semester aktif</small></div><a href="#students" class="sub">Lihat semua murid →</a></div>${st.length?`<div class="table-wrap"><table><thead><tr><th>NAMA MURID</th><th>KEHADIRAN</th><th>NILAI TERISI</th><th>STATUS RAPOR</th></tr></thead><tbody>${st.slice(0,5).map(s=>{const a=C.attendance(db,s.id),filled=as.filter(x=>typeof x.scores[s.id]==='number').length,ready=db.subjects.filter(x=>C.result(db,s.id,x.id).value!==null).length;return `<tr><td>${nameCell(s)}</td><td>${a.percent===null?'Belum dicatat':num(a.percent)+'%'}</td><td>${filled} / ${as.length} asesmen</td><td><span class="pill ${ready<db.subjects.length?'amber':''}">${ready} / ${db.subjects.length} mapel terhitung</span></td></tr>`}).join('')}</tbody></table></div>`:empty('Kelas siap diisi','Isi identitas sekolah dan kelas, lalu tambahkan murid pertama.',btn('new-student','＋ Tambah murid','small'))}</section>`;
}
function students(){const list=C.active(db).filter(s=>(s.name+' '+s.nis+' '+s.nisn).toLowerCase().includes(search.toLowerCase()));return head('Data murid','Satu identitas murid untuk seluruh administrasi kelas.',btn('export-students','↓ Ekspor CSV')+btn('new-student','＋ Tambah murid','primary'))+`<section class="panel"><div class="toolbar"><input type="search" id="student-search" placeholder="Cari nama, NIS, atau NISN…" aria-label="Cari murid" value="${esc(search)}"><span class="sub">${list.length} murid aktif · ${db.students.filter(s=>s.active===false).length} diarsipkan</span>${btn('archived','Lihat arsip','small')}</div>${list.length?`<div class="table-wrap"><table><thead><tr><th>NO.</th><th>NAMA MURID</th><th>NISN</th><th>L/P</th><th>ORANG TUA / WALI</th><th class="no-print">TINDAKAN</th></tr></thead><tbody>${list.map((s,i)=>`<tr><td>${i+1}</td><td>${nameCell(s)}</td><td>${esc(s.nisn||'—')}</td><td>${esc(s.gender||'—')}</td><td>${esc(s.father||s.mother||'Belum diisi')}<div class="sub">${esc(s.phone||'')}</div></td><td class="no-print">${btn('edit-student','Lihat / ubah','small',`data-id="${esc(s.id)}"`)}</td></tr>`).join('')}</tbody></table></div>`:empty('Belum ada murid yang ditampilkan','Tambahkan murid atau ubah kata pencarian.')}</section>`}
function studentForm(id){const s=db.students.find(x=>x.id===id)||{gender:'L'};modal(id?'Identitas murid':'Tambah murid',`<form><div class="form-grid">${input('Nama lengkap *','name',s.name,'text','required maxlength="160"')}${sel('Jenis kelamin','gender',[['L','Laki-laki'],['P','Perempuan'],['','Belum diisi']],s.gender)}${input('NIS','nis',s.nis)}${input('NISN (tetap sebagai teks)','nisn',s.nisn,'text','inputmode="numeric"')}${input('Tempat lahir','birthplace',s.birthplace)}${input('Tanggal lahir','birthdate',s.birthdate,'date')}${input('Agama','religion',s.religion)}${input('Nomor telepon wali','phone',s.phone,'tel')}${textarea('Alamat rumah','address',s.address)}${input('Nama ayah / wali','father',s.father)}${input('Nama ibu','mother',s.mother)}${input('Pekerjaan ayah','fatherJob',s.fatherJob)}${input('Pekerjaan ibu','motherJob',s.motherJob)}</div><div class="form-actions">${id?btn('archive-student','Arsipkan','danger',`data-id="${esc(id)}"`):''}${btn('close','Batal','','type="button"')}<button class="primary" type="submit">Simpan murid</button></div></form>`,f=>{const values=Object.fromEntries(f);values.name=values.name.trim();values.nis=values.nis.trim();values.nisn=values.nisn.trim();if(!values.name)return toast('Nama murid wajib diisi.');if(db.students.some(x=>x.id!==id&&((values.nis&&x.nis===values.nis)||(values.nisn&&x.nisn===values.nisn))))return toast('NIS atau NISN sudah dipakai murid lain.');if(mutate(d=>{if(id)Object.assign(d.students.find(x=>x.id===id),values);else d.students.push({id:uid('s'),active:true,...values})})){close();render();toast('Identitas murid tersimpan.')}})}
function attendanceChart(){
 const month=attDate.slice(0,7),last=new Date(Number(month.slice(0,4)),Number(month.slice(5)),0).getDate();
 const [start,end]=attChartPeriod==='day'?[attDate,attDate]:attChartPeriod==='semester'?[db.settings.start,db.settings.end]:[month+'-01',month+'-'+last];
 const a=C.attendance(db,null,start,end),labels=[['H','Hadir','#237d62'],['S','Sakit','#bc7a13'],['I','Izin','#4379bb'],['A','Alpa','#c45261']];let offset=0;
 const segments=labels.map(([key,label,color])=>{const amount=a.total?100*a[key]/a.total:0,part=amount?`<circle cx="100" cy="100" r="76" fill="none" stroke="${color}" stroke-width="26" pathLength="100" stroke-dasharray="${amount} ${100-amount}" stroke-dashoffset="${-offset}" transform="rotate(-90 100 100)"/>`:'';offset+=amount;return part}).join('');
 return `<section class="panel attendance-summary" aria-labelledby="attendance-chart-title"><div class="panel-head"><div><h2 id="attendance-chart-title">Rekapitulasi kehadiran</h2><p class="sub">${niceDate(start)}${end!==start?' – '+niceDate(end):''}</p></div><label class="field no-print">Periode diagram<select id="att-chart-period">${opts([['day','Tanggal dipilih'],['month','Bulan dari tanggal dipilih'],['semester','Rentang semester aktif']],attChartPeriod)}</select></label></div><div class="attendance-chart-layout"><div class="attendance-donut"><svg viewBox="0 0 200 200" role="img" aria-label="${a.total?'Diagram kehadiran: '+labels.map(([k,l])=>l+' '+a[k]).join(', '):'Belum ada catatan kehadiran dalam periode ini'}"><circle cx="100" cy="100" r="76" fill="none" stroke="#e5ebe7" stroke-width="26"/>${segments}</svg><div class="donut-label" aria-hidden="true"><strong>${a.total}</strong><span>catatan</span></div></div><div class="attendance-legend">${labels.map(([k,l,color])=>`<div class="attendance-legend-row" data-status="${k}"><span class="legend-dot" style="background:${color}"></span><span>${l}</span><strong>${a[k]}</strong><span>${a.total?num(100*a[k]/a.total)+'%':'—'}</span></div>`).join('')}<p class="helper">${a.total?'Persentase dihitung dari '+a.total+' catatan murid per hari, termasuk murid yang telah diarsipkan.':'Belum ada catatan pada periode ini.'} Tanggal kosong dan hari libur tidak dihitung sebagai alpa.</p></div></div></section>`;
}
function attendance(){const holiday=C.holiday(db,attDate),st=C.active(db),at=C.attendance(db,null,attDate,attDate);return head('Daftar hadir','Catat hadir, sakit, izin, dan tanpa keterangan. Perubahan langsung tersimpan.',btn('attendance-holidays','Atur hari libur')+btn('attendance-recap','Rekap bulanan')+btn('export-attendance','↓ Ekspor CSV'))+attendanceChart()+`${holiday?`<div class="notice green"><b>Hari libur: ${esc(holiday.label)}</b><br>Presensi tanggal ini tidak dihitung. Catatan lama tetap tersimpan dan kembali berlaku jika tanggal ini menjadi hari sekolah.</div>`:''}<h3>Kehadiran pada ${niceDate(attDate)}</h3><div class="mini-grid">${[['H','Hadir'],['S','Sakit'],['I','Izin'],['A','Tanpa keterangan']].map(([k,l])=>`<div class="status-${k}"><b>${at[k]}</b>${l}</div>`).join('')}</div><section class="panel"><div class="toolbar"><label>Tanggal <input type="date" id="att-date" value="${attDate}"></label><label>Hari sekolah <select id="att-school-days">${opts([[5,'5 hari (Senin–Jumat)'],[6,'6 hari (Senin–Sabtu)']],C.schoolDays(db))}</select></label><span class="sub">${holiday?'Hari libur':st.filter(s=>db.attendance.some(a=>a.date===attDate&&a.studentId===s.id)).length+' / '+st.length+' murid telah dicatat'}</span>${btn('all-present','✓ Isi yang kosong: hadir','small',holiday?'disabled':'')}${btn('print-output','Cetak','small')}</div>${st.length?`<div class="table-wrap"><table><thead><tr><th>NO.</th><th>NAMA MURID</th><th>STATUS KEHADIRAN</th><th>REKAP SEMESTER (H / S / I / A)</th></tr></thead><tbody>${st.map((s,i)=>{const v=db.attendance.find(a=>a.studentId===s.id&&a.date===attDate)?.status||'',a=C.attendance(db,s.id);return `<tr><td>${i+1}</td><td>${nameCell(s)}</td><td><select ${holiday?'disabled':''} class="status-select status-${v}" data-att="${esc(s.id)}" aria-label="Kehadiran ${esc(s.name)}">${opts([['',holiday?holiday.label:'Belum dicatat'],['H','Hadir'],['S','Sakit'],['I','Izin'],['A','Tanpa keterangan']],holiday?'':v)}</select></td><td>${a.H} / ${a.S} / ${a.I} / ${a.A}</td></tr>`}).join('')}</tbody></table></div>`:empty('Tambahkan murid terlebih dahulu','Daftar presensi mengikuti data murid aktif.','<a href="#students">Buka data murid →</a>')}</section><p class="helper">Tanggal tanpa catatan tidak dianggap hadir atau alpa. Gunakan Atur hari libur untuk memilih tanggal dan mengisi keterangan yang akan tampil dalam unduhan. Rekap semester menggunakan rentang tanggal di Data kelas.</p>`}


function attendanceHolidaysDialog(){
 const draft=new Map(C.manualHolidays(db).map(h=>[h.date,h.label]));let month=attDate.slice(0,7),schoolDays=C.schoolDays(db);
 const auto=date=>C.weekendHoliday({settings:{schoolDays}},date);
 modal('Atur hari libur',`<form><p class="sub">Sekolah 5 hari: Sabtu dan Minggu otomatis Hari libur. Sekolah 6 hari: hanya Minggu. Pilih tanggal lain untuk menambahkan libur khusus.</p><div class="form-grid"><label class="field">Hari sekolah<select id="holiday-school-days">${opts([[5,'5 hari (Senin–Jumat)'],[6,'6 hari (Senin–Sabtu)']],schoolDays)}</select></label><label class="field">Bulan<input type="month" id="holiday-month" value="${month}" required></label></div><div class="actions" style="margin:12px 0"><button type="button" id="holiday-clear">Hapus libur tambahan bulan ini</button></div><div id="holiday-days" style="max-height:42vh;overflow:auto;border:1px solid #e4e8e1;border-radius:8px;padding:12px"></div><p class="helper">Libur otomatis berlaku pada semua bulan. Keterangan boleh disesuaikan (maksimal 40 karakter). Catatan presensi tetap tersimpan, tetapi tidak dihitung pada hari libur. Perubahan berlaku setelah disimpan.</p><div class="form-actions">${btn('close','Batal','','type="button"')}<button type="submit" class="primary">Simpan hari libur</button></div></form>`,()=>{
  if(mutate(d=>{d.settings.schoolDays=schoolDays;d.attendanceHolidays=[...draft].map(([date,label])=>({date,label:label.trim()||'Hari libur'})).sort((a,b)=>a.date.localeCompare(b.date))})){close();render();toast('Hari sekolah dan hari libur tersimpan.')}
 });
 const days=()=>{const last=new Date(Number(month.slice(0,4)),Number(month.slice(5,7)),0).getDate();return Array.from({length:last},(_,i)=>month+'-'+String(i+1).padStart(2,'0'))};
 const paint=()=>{
  $('#holiday-days').innerHTML=days().map(date=>{
   const automatic=auto(date),checked=!!automatic||draft.has(date);
   return `<div style="display:grid;grid-template-columns:minmax(110px,1fr) minmax(130px,2fr);gap:10px;align-items:center;margin-bottom:8px"><label style="display:flex;gap:8px;align-items:center"><input type="checkbox" data-holiday-date="${date}" ${checked?'checked':''} ${automatic?'disabled':''}>${esc(new Date(date+'T12:00:00Z').toLocaleDateString('id-ID',{weekday:'short',day:'numeric',month:'short',timeZone:'UTC'}))}${automatic?' · otomatis':''}</label><input data-holiday-label="${date}" value="${esc(draft.get(date)||automatic?.label||'')}" maxlength="40" placeholder="Contoh: Libur nasional" aria-label="Keterangan libur ${date}" ${checked?'':'disabled'}></div>`;
  }).join('');
  $$('[data-holiday-date]').forEach(el=>el.onchange=()=>{const date=el.dataset.holidayDate;if(auto(date))return;if(el.checked)draft.set(date,'Hari libur');else draft.delete(date);paint()});
  $$('[data-holiday-label]').forEach(el=>el.oninput=()=>{const date=el.dataset.holidayLabel,value=el.value;if(auto(date)&&(!value.trim()||value.trim()==='Hari libur'))draft.delete(date);else draft.set(date,value)});
 };
 $('#holiday-school-days').onchange=e=>{const value=Number(e.target.value);if([5,6].includes(value)){schoolDays=value;paint()}};
 $('#holiday-month').onchange=e=>{if(/^\d{4}-(0[1-9]|1[0-2])$/.test(e.target.value)){month=e.target.value;paint()}};
 $('#holiday-clear').onclick=()=>{for(const date of days())draft.delete(date);paint()};
 paint();
}

function attendanceRecap(){const st=db.students;modal('Rekap kehadiran bulanan',`<label class="field">Bulan<input type="month" id="recap-month" value="${attMonth}"></label><div id="recap-table"></div><div class="form-actions">${btn('close','Tutup')}</div>`);const update=()=>{attMonth=$('#recap-month').value;if(!attMonth)return;$('#recap-table').innerHTML=`<div class="table-wrap"><table><thead><tr><th>Murid</th><th>H</th><th>S</th><th>I</th><th>A</th><th>%</th></tr></thead><tbody>${st.map(s=>{const a=C.attendance(db,s.id,attMonth+'-01',attMonth+'-31');return `<tr><td>${esc(s.name)}</td><td>${a.H}</td><td>${a.S}</td><td>${a.I}</td><td>${a.A}</td><td>${num(a.percent)}</td></tr>`}).join('')}</tbody></table></div>`};$('#recap-month').onchange=update;update()}
function gradeList(){return db.assessments.filter(a=>a.subjectId===gradeSubject&&a.type===gradeType&&a.period===(gradeScope==='review'?'review':C.period(db)))}
function grades(){if(!db.subjects.some(s=>s.id===gradeSubject))gradeSubject=db.subjects[0]?.id||'';const list=gradeList(),st=C.active(db);return head('Asesmen & nilai','Nilai per tujuan pembelajaran, terhubung dengan perkembangan setiap murid.',btn('export-grades','↓ Ekspor CSV')+btn('new-assessment','＋ Tambah asesmen','primary'))+`<div class="tabs">${Object.entries(C.types).map(([k,l])=>btn('grade-type',l,gradeType===k?'selected':'',`data-id="${k}"`)).join('')}</div><section class="panel"><div class="toolbar"><label>Mata pelajaran <select id="grade-subject">${opts(subOpts(),gradeSubject)}</select></label><label>Periode <select id="grade-scope">${opts([['current','Semester aktif'],['review','Impor: perlu ditinjau']],gradeScope)}</select></label><span class="sub">${list.length} asesmen</span></div>${C.isReligionSubject(db,gradeSubject)?'<div class="notice green" style="margin:18px">Pendidikan Agama dan Budi Pekerti: isi nilai hanya untuk TP yang diikuti murid. TP yang seluruh nilainya kosong untuk murid tersebut tidak diwajibkan dan tidak dihitung sebagai nol. Setelah satu nilai TP terisi, lengkapi asesmen lain pada TP yang sama. Setiap kategori berbobot tetap memerlukan nilai. Data agama murid tidak diubah.</div>':''}${gradeScope==='review'?`<div class="notice" style="margin:18px">Nilai ini belum masuk rapor. Periksa tahun dan semester melalui <a href="#backup"><b>Cadangan & data</b></a>.</div>`:''}${list.length&&st.length?`<div class="table-wrap grade-wrap"><table class="grade-table"><thead><tr><th>NAMA MURID</th>${list.map(a=>`<th><b>${esc(a.tp)}</b><br>${esc(a.label)}<br><span>${a.date?niceDate(a.date,true):'Tanpa tanggal'}</span><br>${btn('edit-assessment','Ubah','link no-print',`data-id="${esc(a.id)}"`)}</th>`).join('')}<th>RERATA INPUT</th></tr></thead><tbody>${st.map(s=>`<tr><td>${nameCell(s)}</td>${list.map(a=>`<td><input class="score" type="number" inputmode="numeric" min="0" max="100" step="1" placeholder="—" aria-label="${esc(s.name+' '+a.tp+' '+a.label)}" value="${a.scores[s.id]??''}" data-score="${esc(a.id)}" data-student="${esc(s.id)}"></td>`).join('')}<td id="avg-${esc(s.id)}">${num(C.mean(list.map(a=>a.scores[s.id]).filter(v=>typeof v==='number')))}</td></tr>`).join('')}</tbody></table></div>`:empty('Belum ada asesmen pada pilihan ini','Tambahkan asesmen atau pilih periode impor untuk meninjau nilai dari Excel.',btn('new-assessment','＋ Tambah asesmen','small'))}</section><div class="notice green">${C.isReligionSubject(db,gradeSubject)?'TP yang tidak diikuti boleh dikosongkan; nilai kosong dalam TP yang sudah diikuti perlu dilengkapi.':'Isian kosong berarti belum dinilai;'} angka 0 adalah nilai yang sah. Rerata input di tabel hanya ringkasan. Rapor menghitung rerata per TP, lalu rerata kategori sesuai bobot di Pengaturan.</div>`}
function assessmentForm(id){if(!db.subjects.length){location.hash='subjects';return toast('Tambahkan mata pelajaran terlebih dahulu.');}const a=db.assessments.find(x=>x.id===id)||{subjectId:gradeSubject,type:gradeType,date:today(),period:C.period(db),tp:'',label:''};modal(id?'Ubah asesmen':'Tambah asesmen',`<form><div class="form-grid">${sel('Mata pelajaran','subjectId',subOpts(),a.subjectId)}${sel('Jenis asesmen','type',Object.entries(C.types),a.type)}${input('Tujuan pembelajaran (TP) *','tp',a.tp,'text','required maxlength="240"')}${input('Nama kegiatan / asesmen *','label',a.label,'text','required maxlength="160"')}${input('Tanggal (boleh kosong untuk impor)','date',a.date,'date')}<div class="field">Periode<span class="pill ${a.period==='review'?'amber':''}">${esc(a.period==='review'?'Perlu ditinjau':a.period.replace('|',' · Semester '))}</span></div></div>${a.source?`<p class="helper">Sumber: ${esc(a.source)} · Tahun sumber ${esc(a.sourceYear)}</p>`:''}<div class="form-actions">${id?btn('delete-assessment','Hapus asesmen','danger',`data-id="${esc(id)}" type="button"`):''}${btn('close','Batal','','type="button"')}<button class="primary">Simpan asesmen</button></div></form>`,f=>{const v=Object.fromEntries(f);if(!v.tp.trim()||!v.label.trim())return toast('Tujuan dan nama asesmen wajib diisi.');if(mutate(d=>{if(id)Object.assign(d.assessments.find(x=>x.id===id),v);else d.assessments.push({...v,id:uid('a'),period:C.period(d),scores:{}})})){gradeSubject=v.subjectId;gradeType=v.type;gradeScope=a.period==='review'?'review':'current';close();render();toast('Asesmen tersimpan.')}})}
function journal(){const list=db.journals.filter(j=>j.period===C.period(db)&&(!journalMonth||j.date.startsWith(journalMonth))).sort((a,b)=>a.date.localeCompare(b.date));return head('Jurnal mengajar','Susun jurnal KBM bulanan, lalu tinjau dan lengkapi catatan pelaksanaannya.',btn('journal-planner','Susun jurnal bulanan')+btn('new-journal','＋ Tulis jurnal','primary'))+`<section class="panel"><div class="toolbar"><label>Bulan <input type="month" id="journal-month" value="${journalMonth}"></label>${btn('clear-journal-filter','Semua bulan','small')}<span class="sub">${list.length} pertemuan · ${list.reduce((sum,j)=>sum+j.jp,0)} JP</span>${btn('print-output','Cetak / unduh','small')}${btn('export-journal-word','Unduh Word (.doc)','small')}</div>${list.length?`<div class="table-wrap"><table class="journal-kbm"><thead><tr><th>Tanggal</th><th>Mata pelajaran</th><th>Tujuan pembelajaran</th><th>Rincian kegiatan pembelajaran</th><th>Media pembelajaran</th><th>Asesmen</th><th>Keterangan</th><th class="no-print">Tindakan</th></tr></thead><tbody>${list.map(j=>`<tr><td>${niceDate(j.date)}</td><td>${esc(subject(j.subjectId))}<br>${j.jp} JP</td><td><div class="edit-cell" contenteditable="true" spellcheck="false" data-jid="${esc(j.id)}" data-jfield="tp">${esc(j.tp)}</div></td><td><div class="edit-cell" contenteditable="true" spellcheck="false" data-jid="${esc(j.id)}" data-jfield="activity">${esc(j.activity)}</div></td><td><div class="edit-cell" contenteditable="true" spellcheck="false" data-jid="${esc(j.id)}" data-jfield="media">${esc(j.media||'')}</div></td><td><div class="edit-cell" contenteditable="true" spellcheck="false" data-jid="${esc(j.id)}" data-jfield="assessment">${esc(j.assessment||'')}</div></td><td><div class="edit-cell" contenteditable="true" spellcheck="false" data-jid="${esc(j.id)}" data-jfield="remarks">${esc(j.remarks||'')}</div>${j.reflection||j.followup?`<div class="sub extra-note">${esc([j.reflection?'Refleksi: '+j.reflection:'',j.followup?'Tindak lanjut: '+j.followup:''].filter(Boolean).join('\n'))}</div>`:''}</td><td class="no-print">${btn('edit-journal','Ubah','small',`data-id="${esc(j.id)}"`)}</td></tr>`).join('')}</tbody></table></div>`:empty('Jurnal mengajar belum diisi','Tulis satu pertemuan atau susun draf sebulan berdasarkan jadwal dan TP.',btn('journal-planner','Susun jurnal bulanan','small'))}</section><p class="helper">Format unduhan mengikuti tabel KBM, dengan tanda tangan kepala sekolah dan guru kelas. Media, asesmen, dan keterangan juga tersedia pada template Excel bulanan. Klik langsung pada kolom TP, kegiatan, media, asesmen, atau keterangan untuk menyunting; perubahan tersimpan otomatis saat Anda klik di luar sel.</p>`}
function journalForm(id){if(!db.subjects.length){location.hash='subjects';return toast('Tambahkan mata pelajaran terlebih dahulu.');}const j=db.journals.find(x=>x.id===id)||{date:today(),subjectId:db.subjects[0]?.id,jp:2};modal(id?'Ubah jurnal mengajar':'Jurnal mengajar baru',`<form><div class="form-grid">${input('Tanggal *','date',j.date,'date','required')}${sel('Mata pelajaran','subjectId',subOpts(),j.subjectId)}${input('Alokasi waktu (JP) *','jp',j.jp,'number','min="0.5" max="24" step="0.5" required')}${input('Tujuan pembelajaran *','tp',j.tp,'text','required')}${textarea('Kegiatan pembelajaran *','activity',j.activity,'required')}${textarea('Media pembelajaran','media',j.media||'')}${textarea('Asesmen / teknik penilaian','assessment',j.assessment||'')}${textarea('Keterangan','remarks',j.remarks||'')}${textarea('Refleksi / hasil pengamatan','reflection',j.reflection)}${textarea('Tindak lanjut / pengayaan / pendampingan','followup',j.followup)}</div><div class="form-actions">${id?btn('delete-journal','Hapus','danger',`data-id="${esc(id)}" type="button"`):''}${btn('close','Batal','','type="button"')}<button class="primary">Simpan jurnal</button></div></form>`,f=>{const v=Object.fromEntries(f);v.jp=Number(v.jp);if(mutate(d=>{if(id)Object.assign(d.journals.find(x=>x.id===id),v);else d.journals.push({...v,id:uid('j'),period:C.period(d)})})){close();render();toast('Jurnal tersimpan.')}})}
function description(sid,sub,type='sumative'){const th=db.settings.threshold,list=db.assessments.filter(a=>a.period===C.period(db)&&a.subjectId===sub&&a.type===type&&typeof a.scores[sid]==='number');if(!list.length)return 'Belum ada bukti asesmen '+C.types[type].toLowerCase()+' untuk menyusun deskripsi.';const group=Object.create(null),named=list.filter(a=>a.tp&&a.tp.trim());named.forEach(a=>(group[a.tp.trim()]??=[]).push(a.scores[sid]));const g=Object.entries(group).map(([tp,vals])=>[tp,C.mean(vals)]).sort((a,b)=>b[1]-a[1]);if(!g.length){const v=Math.round(C.mean(list.map(a=>a.scores[sid])));return 'Nilai '+C.types[type].toLowerCase()+' '+(v>=th?'telah mencapai':'belum mencapai')+' batas ketercapaian ('+th+').'}const strong=g.filter(x=>x[1]>=th),weak=g.filter(x=>x[1]<th);return [strong.length?'Menunjukkan ketercapaian pada '+strong.map(x=>x[0]).join('; ')+'.':'',weak.length?'Perlu pendampingan pada '+weak.map(x=>x[0]).join('; ')+'.':''].filter(Boolean).join(' ')}
function noteKey(sid,sub='wali'){return C.period(db)+'|'+sid+'|'+sub}
function extracurricularPreview(sid){const rows=C.extracurriculars(db,sid);return `<h3>B. Ekstrakurikuler</h3><div class="table-wrap"><table><thead><tr><th>No.</th><th>Kegiatan ekstrakurikuler</th><th style="min-width:160px;width:20%">Penilaian</th><th>Keterangan / capaian</th></tr></thead><tbody>${rows.length?rows.map((r,i)=>`<tr><td>${i+1}</td><td>${esc(r.name)}</td><td style="min-width:160px;white-space:nowrap">${esc(r.rating||'Belum dinilai')}</td><td class="wrap-text">${esc(r.description||'—')}</td></tr>`).join(''):'<tr><td colspan="4">Belum ada kegiatan ekstrakurikuler.</td></tr>'}</tbody></table></div>`}
function extracurricularPage(){const st=C.active(db);return head('Ekstrakurikuler','Catat beberapa kegiatan dan penilaian untuk setiap murid pada semester aktif.',btn('new-extracurricular','＋ Input ekstrakurikuler','primary'))+`<section class="panel"><p class="helper" style="padding:0 16px">Klik Tambah kegiatan pada nama murid untuk menambah ekstrakurikuler lain. Setiap kegiatan memiliki penilaian dan keterangan sendiri. Template Excel dapat menyiapkan beberapa baris per murid. Penilaian: Kurang, Cukup, Baik, atau Sangat Baik.</p>${st.length?`<div class="table-wrap"><table><thead><tr><th>Nama murid</th><th>Kegiatan</th><th style="min-width:160px;width:20%">Penilaian</th><th>Keterangan / capaian</th><th>Tindakan</th></tr></thead><tbody>${st.map(s=>{const rows=C.extracurriculars(db,s.id),studentCell=`<td rowspan="${Math.max(1,rows.length)}" style="vertical-align:top"><b>${esc(s.name)}</b><div class="sub">${rows.length} kegiatan</div>${btn('new-extracurricular','＋ Tambah kegiatan','small',`data-id="${esc(s.id)}" aria-label="Tambah kegiatan untuk ${esc(s.name)}"`)}</td>`;return rows.length?rows.map((r,i)=>`<tr>${i===0?studentCell:''}<td>${esc(r.name)}</td><td style="min-width:160px;white-space:nowrap">${esc(r.rating||'Belum dinilai')}</td><td class="wrap-text">${esc(r.description||'—')}</td><td>${btn('edit-extracurricular','Ubah','small',`data-id="${esc(r.id)}"`)}</td></tr>`).join(''):`<tr>${studentCell}<td colspan="4" class="sub">Belum diisi</td></tr>`}).join('')}</tbody></table></div>`:empty('Belum ada murid','Tambahkan murid pada menu Data murid.')}</section>`}

function extracurricularForm(id,sid){const st=C.active(db);if(!st.length)return toast('Tambahkan murid terlebih dahulu.');const record=(db.extracurriculars||[]).find(r=>r.id===id),r=record||{studentId:sid||st[0].id,name:'',description:''},period=record?.period||C.period(db);modal(record?'Ubah ekstrakurikuler':'Input ekstrakurikuler',`<form><p class="sub">Tahun ${esc(db.settings.year)} · Semester ${esc(db.settings.semester)}</p><div class="form-grid">${sel('Murid','studentId',st.map(s=>[s.id,s.name]),r.studentId,'required')}${input('Nama kegiatan *','name',r.name,'text','required maxlength="120" placeholder="Contoh: Pramuka"')}${sel('Penilaian *','rating',[['','Pilih penilaian'],...C.extracurricularRatings.map(v=>[v,v])],r.rating||'','required')}${textarea('Keterangan / capaian','description',r.description,'maxlength="1000" placeholder="Contoh: Aktif mengikuti kegiatan dan mampu bekerja sama dengan baik."')}</div><div class="form-actions">${record?btn('delete-extracurricular','Hapus kegiatan','danger',`type="button" data-id="${esc(id)}"`):''}${btn('close','Batal','','type="button"')}${!record?'<button type="submit" data-extra-more="true">Simpan & tambah lagi</button>':''}<button class="primary" type="submit">Simpan ekstrakurikuler</button></div></form>`,(f,form,submitter)=>{const value=Object.fromEntries(f);value.name=value.name.trim();value.description=value.description.trim();if(!value.name)return toast('Nama kegiatan wajib diisi.');if(!C.extracurricularRatings.includes(value.rating))return toast('Pilih penilaian Kurang, Cukup, Baik, atau Sangat Baik.');if((db.extracurriculars||[]).some(x=>x.id!==id&&x.studentId===value.studentId&&x.period===period&&x.name.trim().toLocaleLowerCase('id-ID')===value.name.toLocaleLowerCase('id-ID')))return toast('Kegiatan ini sudah tercatat untuk murid dan semester tersebut. Gunakan Ubah untuk memperbaruinya.');if(mutate(d=>{d.extracurriculars??=[];if(record)Object.assign(d.extracurriculars.find(x=>x.id===id),value);else d.extracurriculars.push({...value,id:uid('extra'),period})})){close();render();toast('Ekstrakurikuler tersimpan.');if(submitter?.dataset.extraMore==='true')extracurricularForm(null,value.studentId);}})}

function reports(){const st=C.active(db);if(!st.some(s=>s.id===reportStudent))reportStudent=st[0]?.id||'';const s=st.find(x=>x.id===reportStudent);return head('Pengolahan rapor','Pratinjau hasil perhitungan. Tinjau kelengkapan dan deskripsi sebelum digunakan.',btn('export-report','↓ Rekap CSV')+btn('class-notes','✎ Tulis catatan wali kelas')+btn('print-output','↓ Unduh rapor (A4 portrait)','primary'))+`<div class="panel no-print"><div class="toolbar"><label>Murid <select id="report-student">${opts(st.map(x=>[x.id,x.name]),reportStudent)}</select></label>${btn('edit-report-notes','Ubah deskripsi & catatan','small')+btn('report-extracurricular','Input ekstrakurikuler','small')}<a href="#settings" class="sub">Atur bobot nilai →</a></div></div>`+sigPanel()+(!s?empty('Belum ada murid','Tambahkan murid dan mata pelajaran untuk mulai mengolah rapor.'):renderReport(s))}
let sigClean=true;
function sigPanel(){const s=db.settings,box=(key,label,name)=>`<div class="sig-box"><b>${label}</b><small>${esc(name||'Nama belum diisi pada Data sekolah / Data kelas')}</small><div class="sig-preview">${s[key]?`<img src="${esc(s[key])}" alt="Tanda tangan ${esc(label)}">`:'<span>Belum ada tanda tangan</span>'}</div><div class="sig-actions"><label class="sig-upload">${s[key]?'Ganti gambar':'Unggah gambar'}<input type="file" accept="image/png,image/jpeg" data-sig-file="${key}" hidden></label>${s[key]?btn('clear-sig','Hapus','small',`data-id="${key}"`):''}</div></div>`;return `<section class="panel no-print"><div class="panel-head"><div><h2>Tanda tangan</h2><small>Unggah gambar tanda tangan (PNG/JPG). Dicetak di atas nama pada rapor dan laporan unduhan.</small></div></div><div class="panel-body"><div class="sig-grid">${box('principalSig',C.principalTitle(db),s.principal)}${box('teacherSig','Guru / wali kelas',s.teacher)}</div><label class="sig-opt"><input type="checkbox" id="sig-transparent" ${sigClean?'checked':''}> Hapus latar putih otomatis (disarankan untuk foto atau pindaian tanda tangan)</label></div></section>`}
function sigUpload(inp){const key=inp.dataset.sigFile,file=inp.files[0];inp.value='';if(!file)return;if(!/^image\/(png|jpeg)$/.test(file.type))return toast('Pilih gambar berformat PNG atau JPG.');if(file.size>5*1024*1024)return toast('Ukuran gambar maksimal 5 MB.');const fr=new FileReader();fr.onload=()=>{const img=new Image();img.onload=()=>{const k=Math.min(1,600/img.width,300/img.height),cv=document.createElement('canvas');cv.width=Math.max(1,Math.round(img.width*k));cv.height=Math.max(1,Math.round(img.height*k));const cx=cv.getContext('2d');cx.drawImage(img,0,0,cv.width,cv.height);let type=file.type==='image/png'?'image/png':'image/jpeg';if(sigClean){const im=cx.getImageData(0,0,cv.width,cv.height),px=im.data;for(let i=0;i<px.length;i+=4){const lum=Math.min(px[i],px[i+1],px[i+2]);if(lum>=228)px[i+3]=0;else if(lum>190)px[i+3]=Math.round(px[i+3]*(228-lum)/38)}cx.putImageData(im,0,0);type='image/png'}const url=cv.toDataURL(type,.92);if(mutate(d=>{d.settings[key]=url})){render();toast('Tanda tangan tersimpan.')}};img.onerror=()=>toast('Gambar tidak dapat dibaca.');img.src=fr.result};fr.readAsDataURL(file)}
function renderReport(s){const a=C.attendance(db,s.id),settings=db.settings,missing=db.subjects.filter(x=>C.result(db,s.id,x.id).value===null);return `<div class="notice no-print">${missing.length?`${missing.length} mata pelajaran belum lengkap untuk dihitung. `:''}Pratinjau ini adalah lembar pengolahan rapor internal. Deskripsi otomatis perlu ditinjau guru; format penerbitan mengikuti ketentuan sekolah.</div><section class="panel"><div class="report"><div class="report-title"><div class="eyebrow">LAPORAN HASIL BELAJAR · PRATINJAU</div><h2>${esc(settings.school)}</h2><p>${esc(settings.schoolAddress)}</p></div><div class="report-meta"><span>Nama murid: <b>${esc(s.name)}</b></span><span>Kelas / semester: <b>${esc(settings.className)} / ${settings.semester}</b></span><span>NIS / NISN: ${esc(s.nis)} / ${esc(s.nisn)}</span><span>Tahun pelajaran: ${esc(settings.year)}</span></div><h3>A. Nilai dan Capaian Kompetensi</h3><div class="table-wrap"><table><thead><tr><th style="width:35px">No.</th><th style="width:24%">Mata pelajaran</th><th style="width:90px">Nilai akhir</th><th>Deskripsi capaian pembelajaran</th></tr></thead><tbody>${db.subjects.map((sub,i)=>{const r=C.result(db,s.id,sub.id);return `<tr><td>${i+1}</td><td>${esc(sub.name)}</td><td><b>${num(r.value)}</b>${r.missing.length?'<div class="sub">Belum lengkap</div>':''}</td><td class="desc">${esc(db.reportNotes[noteKey(s.id,sub.id)]||description(s.id,sub.id))}</td></tr>`}).join('')}</tbody></table></div><p class="helper">Bobot: ${Object.entries(C.reportTypes).filter(([k])=>settings.weights[k]>0).map(([k,v])=>`${v} ${settings.weights[k]}%`).join(' · ')}. Nilai akhir dibulatkan ke bilangan bulat. Komponen berbobot yang belum lengkap tidak dihitung sebagai nol.</p>${optionalPreview(s.id)}${extracurricularPreview(s.id)}<h3 style="margin-top:22px">C. Ketidakhadiran</h3><p class="sub">Rentang rekap: ${niceDate(settings.start)} – ${niceDate(settings.end)}. ${a.total} hari tercatat untuk murid ini.</p><div class="mini-grid"><div><b>${a.H}</b>Hadir</div><div><b>${a.S}</b>Sakit</div><div><b>${a.I}</b>Izin</div><div><b>${a.A}</b>Tanpa keterangan</div></div><h3>D. Catatan Wali Kelas</h3><p class="wrap-text">${esc(db.reportNotes[noteKey(s.id)]||'Catatan wali kelas belum diisi.')}</p><div class="signatures"><div>Mengetahui,<br>Orang tua / wali<b>........................</b></div><div>${esc(settings.city)}, ${niceDate(today())}<br>Wali kelas${settings.teacherSig?`<img class="sig-img" src="${esc(settings.teacherSig)}" alt="Tanda tangan wali kelas">`:''}<b>${esc(settings.teacher)}</b><small>NIP ${esc(settings.teacherNip||'........................')}</small></div><div>${esc(C.principalTitle(db))}${settings.principalSig?`<img class="sig-img" src="${esc(settings.principalSig)}" alt="Tanda tangan kepala sekolah">`:''}<b>${esc(settings.principal||'........................')}</b><small>NIP ${esc(settings.principalNip||'........................')}</small></div></div></div></section>`}
function reportNotesForm(){if(!reportStudent)return toast('Tambahkan murid terlebih dahulu.');modal('Deskripsi & catatan rapor',`<form><p class="sub">Deskripsi awal disusun dari nilai sumatif. Sesuaikan dengan bukti belajar dan pengamatan Bapak/Ibu.</p><div class="form-grid">${db.subjects.map(s=>textarea(s.name,s.id,db.reportNotes[noteKey(reportStudent,s.id)]||description(reportStudent,s.id))).join('')}${textarea('D. Catatan Wali Kelas','wali',db.reportNotes[noteKey(reportStudent)]||'')}${db.reportNotes[noteKey(reportStudent,'parent')]?`<details class="field full"><summary>Catatan wali murid dari versi sebelumnya (tidak dicetak)</summary>${textarea('Catatan tersimpan','parent',db.reportNotes[noteKey(reportStudent,'parent')],'maxlength="2000"')}</details>`:''}</div><div class="form-actions">${btn('close','Batal','','type="button"')}<button class="primary">Simpan catatan</button></div></form>`,f=>{if(mutate(d=>{for(const [k,v]of f)d.reportNotes[noteKey(reportStudent,k)]=v})){close();render();toast('Catatan rapor tersimpan.')}})}
function classNotesForm(){const st=C.active(db);if(!st.length)return toast('Tambahkan murid terlebih dahulu.');modal('Catatan wali kelas',`<form><p class="sub">Tulis catatan wali kelas untuk setiap murid. Catatan tampil pada pratinjau dan pada rapor hasil unduhan (di atas tanda tangan). Kosongkan kolom untuk menghapus catatan.</p><div class="form-grid">${st.map((x,i)=>textarea((i+1)+'. '+x.name,x.id,db.reportNotes[noteKey(x.id)]||'')).join('')}</div><div class="form-actions">${btn('close','Batal','','type="button"')}<button class="primary">Simpan catatan</button></div></form>`,f=>{if(mutate(d=>{for(const [k,v] of f){const key=noteKey(k),t=String(v).trim();if(t)d.reportNotes[key]=t;else delete d.reportNotes[key]}})){close();render();toast('Catatan wali kelas tersimpan.')}})}
function backupPage(){const review=db.assessments.filter(a=>a.period==='review');return head('Cadangan & data','Simpan salinan lengkap, pindahkan perangkat, atau pulihkan pekerjaan Anda.')+`<div class="grid-2" style="grid-template-columns:1fr 1fr"><div class="backup-card"><span class="stat-icon">↓</span><h2>Cadangkan seluruh kelas</h2><p>JSON berisi identitas murid, presensi, asesmen, jurnal, catatan rapor, dan pengaturan.</p>${btn('backup','Unduh cadangan JSON','primary')}</div><div class="backup-card"><span class="stat-icon">↑</span><h2>Pulihkan cadangan JSON</h2><p>Pilih JSON Ruang Kelas. Ringkasan akan ditampilkan sebelum mengganti data pada perangkat ini.</p>${btn('import','Pilih berkas JSON')}</div></div><div class="notice green">Data kerja tersimpan di peramban ini, tanpa sinkronisasi antarperangkat. Menghapus data peramban dapat menghapus pekerjaan. Cadangkan setelah bekerja dan simpan JSON di tempat pribadi.</div><section class="panel"><div class="panel-head"><h2>Isi data saat ini</h2><span class="pill">Versi format 1</span></div><div class="panel-body"><div class="data-summary">${[[db.students.length,'Murid'],[db.attendance.length,'Catatan presensi'],[db.assessments.length,'Asesmen'],[db.journals.length,'Jurnal']].map(([v,l])=>`<div><b>${num(v)}</b><small>${l}</small></div>`).join('')}</div>${btn('recovery','Pulihkan salinan sebelum impor','small')}${storageError?btn('raw-data','Unduh data mentah','small'):''}</div></section><section class="panel"><div class="panel-head"><h2>Tinjauan impor Excel</h2><span class="pill amber">${review.length} asesmen menunggu</span></div><div class="panel-body">${db.importNotes.length?`<ul class="import-list">${db.importNotes.map(n=>`<li>${esc(n)}</li>`).join('')}</ul>`:'<p class="sub">Belum ada catatan impor. Aplikasi dimulai tanpa data bawaan.</p>'}${review.length?`<div class="table-wrap"><table><thead><tr><th>MAPEL</th><th>ASESMEN</th><th>NILAI</th><th>TAHUN SUMBER</th></tr></thead><tbody>${review.map(a=>`<tr><td>${esc(subject(a.subjectId))}</td><td>${esc(a.tp+' · '+a.label)}</td><td>${Object.keys(a.scores).length}</td><td>${esc(a.sourceYear||'—')}</td></tr>`).join('')}</tbody></table></div><p class="helper">Setelah memastikan nilai berasal dari kelas dan periode yang benar, tetapkan semua asesmen tertunda ke semester aktif (${esc(db.settings.year)}, semester ${db.settings.semester}). Sumber asli tetap dicatat.</p>${btn('activate-import','Tetapkan ke semester aktif','primary')}`:''}</div></section><section class="panel"><div class="panel-body"><h3>Urutan penggunaan</h3><p class="sub">1. Isi Data sekolah. 2. Isi Data kelas. 3. Tambahkan Mata pelajaran dan Data murid. 4. Catat presensi, asesmen, dan jurnal. 5. Sesuaikan bobot dan periksa rapor. 6. Unduh cadangan setelah bekerja.</p></div></section>`}
function schoolPage(){const s=db.settings;return head('Data sekolah','Isi identitas sekolah yang akan digunakan pada laporan dan rapor.')+`<form id="school-form"><section class="panel"><div class="panel-head"><h2>Identitas sekolah</h2></div><div class="panel-body form-grid">${input('Nama sekolah *','school',s.school,'text','required')}${input('NPSN','npsn',s.npsn||'','text','inputmode="numeric"')}${input('Kota / kabupaten','city',s.city)}${input('Alamat sekolah','schoolAddress',s.schoolAddress)}${sel('Status kepala sekolah','principalStatus',[['Definitif','Definitif'],['Plt.','Plt. (Pelaksana Tugas)']],s.principalStatus||'Definitif')}${input('Nama kepala sekolah','principal',s.principal)}${input('NIP kepala sekolah','principalNip',s.principalNip)}</div></section><section class=\"panel\"><div class=\"panel-head\"><h2>Kop surat laporan</h2></div><div class=\"panel-body form-grid\">${textarea('Baris kop di atas nama sekolah (opsional, satu baris per teks)','kopLines',s.kopLines||'','rows=\"3\" maxlength=\"600\" placeholder=\"PEMERINTAH KOTA ...&#10;DINAS PENDIDIKAN DAN KEBUDAYAAN\"')}<div class=\"field full\"><span>Logo sekolah (opsional, PNG/JPG)</span><div id=\"logo-box\" style=\"display:flex;gap:12px;align-items:center;flex-wrap:wrap\"><img id=\"logo-preview\" alt=\"\" style=\"height:56px;width:auto;max-width:120px;object-fit:contain;${s.logo?'':'display:none;'}border:1px solid var(--line);border-radius:8px;padding:3px;background:#fff\" ${s.logo?`src=\"${esc(s.logo)}\"`:''}><input type=\"file\" id=\"logo-file\" accept=\"image/png,image/jpeg\"><button type=\"button\" id=\"logo-clear\" ${s.logo?'':'hidden'}>Hapus logo</button><input type=\"hidden\" name=\"logo\" id=\"logo-data\" value=\"${esc(s.logo||'')}\"></div><small class=\"helper\">Logo dan baris kop tampil di bagian atas setiap laporan PDF, Excel, dan HTML. Kosongkan bila tidak diperlukan.</small></div></div></section><div class="form-actions"><a class="button" href="#class">Lanjut ke data kelas →</a><button class="primary" type="submit">Simpan data sekolah</button></div></form>`}
function classPage(){const s=db.settings;return head('Data kelas','Atur identitas kelas, wali kelas, dan periode pembelajaran.')+`<form id="class-form"><section class="panel"><div class="panel-head"><h2>Identitas kelas</h2></div><div class="panel-body form-grid">${input('Nama kelas / rombel *','className',s.className,'text','required placeholder="Contoh: 5 A"')}${input('Nama wali kelas','teacher',s.teacher)}${input('NIP wali kelas','teacherNip',s.teacherNip)}</div></section><section class="panel"><div class="panel-head"><h2>Periode pembelajaran</h2></div><div class="panel-body form-grid">${input('Tahun pelajaran *','year',s.year,'text','required pattern="[0-9]{4}/[0-9]{4}"')}${sel('Semester','semester',[['1','1 · Ganjil'],['2','2 · Genap']],s.semester)}${input('Mulai rekap presensi *','start',s.start,'date','required')}${input('Akhir rekap presensi *','end',s.end,'date','required')}</div></section><p class="helper">Satu ruang kerja digunakan untuk satu kelas. Tahun dan semester awal mengikuti tanggal perangkat; sesuaikan dengan periode yang digunakan. Pergantian semester tidak menghapus data sebelumnya.</p><div class="form-actions"><a class="button" href="#subjects">Lanjut ke mata pelajaran →</a><button class="primary" type="submit">Simpan data kelas</button></div></form>`}
function subjectsPage(){return head('Mata pelajaran','Atur urutan mata pelajaran untuk rapor dan rekapitulasi. Perubahan urutan langsung tersimpan.',btn('new-subject','＋ Tambah mapel','primary'))+`<section class="panel"><div class="panel-head"><h2>Urutan mata pelajaran</h2><span class="pill">${db.subjects.length} mapel</span></div><div class="panel-body"><p class="helper">Gunakan Naik / Turun untuk menyusun urutan yang muncul di laporan akhir.</p>${db.subjects.length?db.subjects.map((s,i)=>`<div class="metric-line subject-order-row"><span><b>${i+1}.</b> ${esc(s.name)}</span><span class="row-actions">${btn('subject-up','↑ Naik','small',`data-id="${esc(s.id)}" aria-label="Naikkan ${esc(s.name)}" ${i===0?'disabled':''}`)}${btn('subject-down','↓ Turun','small',`data-id="${esc(s.id)}" aria-label="Turunkan ${esc(s.name)}" ${i===db.subjects.length-1?'disabled':''}`)}${btn('rename-subject','Ubah nama','link',`data-id="${esc(s.id)}"`)}${btn('delete-subject','Hapus','link danger-link',`data-id="${esc(s.id)}"`)}</span></div>`).join(''):empty('Belum ada mata pelajaran','Tambahkan satu per satu atau isi template Excel lalu impor.',btn('new-subject','＋ Tambah mapel','small'))}</div></section>`}
function optionalPreview(sid){
 const v=C.optionalResult(db,sid),r=C.optionalRecord(db,sid);
 if(!r&&!(db.settings.weights.discipline>0||db.settings.weights.attitude>0))return '';
 return `<h3>Sikap & kedisiplinan</h3><p>Kedisiplinan: <b>${num(v.discipline)}</b> / 100 · Sikap: <b>${num(v.average)}</b> / 5 (${v.filled}/8 dimensi terisi) · Konversi sikap: <b>${num(v.attitude)}</b> / 100</p><p class="sub">Bobot kedisiplinan ${db.settings.weights.discipline||0}% · Bobot sikap ${db.settings.weights.attitude||0}%. <a href="#competency">Lihat / ubah nilai →</a></p>`;
}
function competencyPage(){
 const ctx=Competency.context(db),st=C.active(db),dims=Object.entries(C.dimensions);
 return head('Sikap & kedisiplinan',`Nilai per murid · Tahun ${esc(db.settings.year)} · Semester ${esc(db.settings.semester)}`,'<a class="button" href="#settings">Atur bobot rapor →</a>')+
 `<div class="notice green">Opsional. Kedisiplinan memakai skala 0–100 dan sikap memakai skala 1–5. Bobot saat ini: kedisiplinan <b>${db.settings.weights.discipline||0}%</b>, sikap <b>${db.settings.weights.attitude||0}%</b>. Bobot 0% tidak mengubah nilai rapor. Nilai ini berlaku untuk seluruh mapel pada semester aktif.</div>
 <section class="panel"><div class="panel-head"><h2>Acuan kelas dan fase</h2></div><div class="panel-body">
 <form id="competency-context"><div class="form-grid">${sel('Jenjang','level',[['PAUD','PAUD'],['SD','SD / MI / sederajat'],['SMP','SMP / MTs / sederajat'],['SMA','SMA / MA / sederajat'],['SMK','SMK / MAK']],ctx?.level||'SD')}${sel('Kelas','grade',Competency.grades(ctx?.level||'SD'),ctx?.grade??'','required')}</div><p id="competency-phase" class="helper"></p><button type="submit">Simpan acuan semester ini</button></form>
 <p class="helper">Dokumen sumber mengatur kriteria per jenjang dengan tiga tahap: Berkembang, Cakap, Mahir; tidak merinci per kelas/fase dan tidak menetapkan skala 1–5. Kelas dipakai untuk menampilkan fase dan memilih acuan jenjang. Fase A, B, C menggunakan acuan SD yang sama. Sesuaikan konteks pengamatan dengan kegiatan di kelas.</p>
 <details><summary><b>Lihat kriteria ${esc(ctx?ctx.level+' · '+Competency.phase(ctx):'(pilih acuan dahulu)')}</b></summary>
 <p>Ringkasan acuan Keputusan Kepala BSKAP Nomor 058/H/KR/2025. Nomor halaman merujuk dokumen terlampir.</p>
 ${ctx?dims.map(([k,label],i)=>{const r=Competency.rubrics[ctx.level][i];return `<details style="padding:10px 0;border-bottom:1px solid #e4e8e1"><summary><b>${esc(label)}</b> · hlm. ${esc(r[0])}</summary><dl>${['Berkembang','Cakap','Mahir'].map((t,j)=>`<dt><b>${t}</b></dt><dd style="margin:4px 0 12px">${esc(r[j+1])}</dd>`).join('')}</dl></details>`}).join(''):''}
 <p><button id="competency-source" type="button">↓ Dokumen kriteria lengkap (PDF)</button></p></details>
 <details style="margin-top:14px"><summary><b>Panduan skala angka 1–5 (adaptasi aplikasi)</b></summary><p>Gunakan bukti pengamatan pada dimensi dan jenjang yang dipilih. Pembagian lima angka berikut adalah panduan aplikasi, bukan skala angka dari dokumen.</p><ol>${Competency.scale.map(t=>`<li>${esc(t)}</li>`).join('')}</ol><p>Nilai sikap untuk rapor = rata-rata delapan dimensi ÷ 5 × 100. Contoh: rata-rata 4 menjadi 80. Semua delapan dimensi harus terisi jika bobot Sikap digunakan. Guru memasukkan nilai kedisiplinan sendiri; persentase hadir hanya menjadi informasi pendukung.</p></details>
 </div></section>
 <section class="panel"><div class="panel-head"><h2>Nilai semester aktif</h2><span class="sub">${st.length} murid</span></div>
 ${st.length?`<div class="table-wrap"><table><thead><tr><th>No.</th><th>Nama murid</th><th>Kedisiplinan /100</th><th>Dimensi terisi</th><th>Rerata sikap /5</th><th>Sikap /100</th><th>Tindakan</th></tr></thead><tbody>${st.map((s,i)=>{const v=C.optionalResult(db,s.id);return `<tr><td>${i+1}</td><td>${nameCell(s)}</td><td>${num(v.discipline)}</td><td>${v.filled}/8</td><td>${num(v.average)}</td><td>${num(v.attitude)}</td><td><button type="button" data-competency-edit="${esc(s.id)}">Isi / ubah nilai</button></td></tr>`}).join('')}</tbody></table></div>`:empty('Belum ada murid','Tambahkan murid di halaman Data murid terlebih dahulu.')}
 </section><p class="helper">Klik Isi / ubah nilai untuk mengisi delapan dimensi, kedisiplinan, dan catatan pengamatan. Isian boleh disimpan sebagian. Nilai akhir rapor tetap belum lengkap jika komponen berbobot belum terisi. Cadangan JSON menyimpan seluruh nilai dan acuan semester.</p>`;
}
function bindCompetency(){
 const form=$('#competency-context'),level=form.querySelector('[name=level]'),grade=form.querySelector('[name=grade]');
 const phase=()=>{$('#competency-phase').textContent=grade.value!==''?'Fase '+Competency.phase({level:level.value,grade:Number(grade.value)}):'Pilih kelas untuk menampilkan fase.'};
 level.onchange=()=>{grade.innerHTML=opts(Competency.grades(level.value),'');phase()};grade.onchange=phase;phase();
 form.onsubmit=e=>{e.preventDefault();if(grade.value==='')return toast('Pilih kelas terlebih dahulu.');if(mutate(d=>{d.competencyContexts??={};d.competencyContexts[C.period(d)]={level:level.value,grade:Number(grade.value)}})){render();toast('Acuan kelas dan fase tersimpan untuk semester aktif.')}};
 $('#competency-source').onclick=()=>download('Alur Perkembangan Kompetensi.pdf',Competency.pdf(),'application/pdf');
 $$('[data-competency-edit]').forEach(b=>b.onclick=()=>competencyForm(b.dataset.competencyEdit));
}
function competencyForm(sid){
 const pupil=db.students.find(s=>s.id===sid);if(!pupil)return;
 const ctx=Competency.context(db);if(!ctx)return toast('Simpan jenjang dan kelas acuan terlebih dahulu.');
 const r=C.optionalRecord(db,sid)||{attitudes:{}},a=C.attendance(db,sid),period=C.period(db);
 modal('Sikap & kedisiplinan — '+esc(pupil.name),`<form><p class="sub">${esc(ctx.level)} · Kelas ${ctx.grade||'PAUD'} · Fase ${Competency.phase(ctx)} · ${esc(db.settings.year)} semester ${esc(db.settings.semester)}</p>
 <div class="notice green">Kehadiran tercatat: H ${a.H}, S ${a.S}, I ${a.I}, A ${a.A}. Persentase hadir ${num(a.percent)}${a.percent===null?'':'%'}. Nilai kedisiplinan di bawah ditentukan guru; tidak diisi otomatis dari presensi.</div>
 ${input('Nilai kehadiran (Kedisiplinan) · 0–100','discipline',r.discipline??'','number','min="0" max="100" step="1" inputmode="numeric" placeholder="Belum dinilai"')}
 <h3>Delapan dimensi sikap · 1–5</h3><p class="helper">Kosong = belum dinilai. Pilih angka berdasarkan bukti pengamatan; buka kriteria di setiap dimensi.</p>
 ${Object.entries(C.dimensions).map(([k,label],i)=>{const rubric=Competency.rubrics[ctx.level][i];return `<div style="margin:14px 0;padding:12px;border:1px solid #e4e8e1;border-radius:10px">${sel(label,k,[['','Belum dinilai'],...Competency.scale.map((t,j)=>[j+1,(j+1)+' — '+Competency.scaleShort[j]])],r.attitudes[k]??'')}<details style="margin-top:8px"><summary>Kriteria ${esc(ctx.level)} · hlm. ${rubric[0]}</summary>${['Berkembang','Cakap','Mahir'].map((t,j)=>`<p><b>${t}:</b> ${esc(rubric[j+1])}</p>`).join('')}</details></div>`}).join('')}
 <details><summary>Panduan angka 1–5 (adaptasi aplikasi)</summary><ol>${Competency.scale.map(t=>`<li>${esc(t)}</li>`).join('')}</ol></details>
 ${textarea('Catatan bukti pengamatan (opsional)','note',r.note||'','maxlength="1000" placeholder="Contoh kegiatan, tanggal pengamatan, atau pendampingan yang diperlukan"')}
 <p id="competency-draft-summary" class="helper"></p><div class="form-actions">${btn('close','Batal','','type="button"')}<button type="submit" class="primary">Simpan nilai</button></div></form>`,f=>{
  if(C.period(db)!==period)return toast('Semester berubah. Tutup formulir lalu buka kembali.');
  const record={studentId:sid,period,attitudes:{},note:String(f.get('note')||'').trim()};
  const value=f.get('discipline');if(value!=='')record.discipline=Math.round(Number(value));
  for(const k of Object.keys(C.dimensions))if(f.get(k)!=='')record.attitudes[k]=Number(f.get(k));
  if(mutate(d=>{d.competencyContexts??={};d.competencyContexts[period]??={...ctx};d.competencyScores??=[];d.competencyScores=d.competencyScores.filter(x=>x.studentId!==sid||x.period!==period);if(record.discipline!==undefined||Object.keys(record.attitudes).length||record.note)d.competencyScores.push(record)})){close();render();toast('Nilai sikap dan kedisiplinan tersimpan.')}
 });
 const form=$('#dialog form'),update=()=>{const values=Object.keys(C.dimensions).map(k=>form.elements.namedItem(k).value),complete=values.every(v=>v!=='');$('#competency-draft-summary').textContent=complete?'Rerata sikap '+num(C.mean(values.map(Number)))+' / 5 → '+num(C.mean(values.map(Number))*20)+' / 100.':values.filter(v=>v!=='').length+'/8 dimensi terisi. Rerata dihitung setelah delapan dimensi lengkap.'};
 form.oninput=update;update();
}

function settings(){const s=db.settings;return head('Pengaturan nilai','Sesuaikan bobot asesmen dan batas ketercapaian untuk pengolahan rapor.')+`<form id="settings-form"><section class="panel"><div class="panel-head"><h2>Aturan pengolahan rapor</h2><span class="pill">Dapat disesuaikan sekolah</span></div><div class="panel-body"><div class="weight-row">${Object.entries(C.reportTypes).map(([k,l])=>input(l+' (%)',k,s.weights[k]??0,'number','min="0" max="100" step="1" required')).join('')}</div><p class="helper">Kehadiran (Kedisiplinan) dan Sikap bersifat opsional: bobot 0% tidak memengaruhi rapor. Nilainya diisi di <a href="#competency">Sikap & kedisiplinan</a>, satu kali per murid per semester dan berlaku untuk semua mapel. Sikap = rata-rata delapan dimensi ÷ 5 × 100; seluruh dimensi harus terisi bila bobot Sikap di atas 0%. Total seluruh bobot wajib 100%. Contoh: Sumatif TP 80%, Kedisiplinan 10%, Sikap 10%, kategori lain 0%. Pengaturan awal: sumatif TP 100%; formatif digunakan untuk pemantauan. Ini adalah pilihan awal aplikasi, bukan penetapan kebijakan sekolah.</p><div class="form-grid">${input('Batas ketercapaian untuk deskripsi','threshold',s.threshold,'number','min="0" max="100" required')}</div><p class="helper">Per kategori: rata-rata nilai dalam TP → rata-rata antar-TP → bobot kategori. Semua asesmen terdaftar pada kategori berbobot harus terisi untuk menghasilkan nilai akhir. Nilai kosong tetap belum lengkap; nilai 0 tetap dihitung.</p></div></section><div class="form-actions"><button class="primary" type="submit">Simpan pengaturan</button></div></form>`}
function bindPage(){
 if(page==='analysis')bindAnalysis();
 if(page==='competency')bindCompetency();
 const logoFile=$('#logo-file');if(logoFile){const prev=$('#logo-preview'),data=$('#logo-data'),clear=$('#logo-clear');
  logoFile.onchange=()=>{const file=logoFile.files[0];logoFile.value='';if(!file)return;if(!/^image\/(png|jpeg)$/.test(file.type))return toast('Pilih logo berformat PNG atau JPG.');if(file.size>5*1024*1024)return toast('Ukuran logo maksimal 5 MB.');const fr=new FileReader();fr.onload=()=>{const img=new Image();img.onload=()=>{const k=Math.min(1,300/Math.max(img.width,img.height)),cv=document.createElement('canvas');cv.width=Math.max(1,Math.round(img.width*k));cv.height=Math.max(1,Math.round(img.height*k));cv.getContext('2d').drawImage(img,0,0,cv.width,cv.height);const url=cv.toDataURL(file.type==='image/png'?'image/png':'image/jpeg',.9);data.value=url;prev.src=url;prev.style.display='';clear.hidden=false;toast('Logo siap. Klik Simpan data sekolah.')};img.onerror=()=>toast('Logo tidak dapat dibaca.');img.src=fr.result};fr.readAsDataURL(file)};
  clear.onclick=()=>{data.value='';prev.removeAttribute('src');prev.style.display='none';clear.hidden=true};}
 for(const kind of ['school','class']){const form=$('#'+kind+'-form');if(form)form.onsubmit=e=>{e.preventDefault();const f=Object.fromEntries(new FormData(form));Object.keys(f).forEach(k=>f[k]=f[k].trim());if(kind==='school'&&!f.school)return toast('Nama sekolah wajib diisi.');if(kind==='class'){if(!f.className)return toast('Nama kelas wajib diisi.');if(!C.dateValid(f.start)||!C.dateValid(f.end)||f.start>f.end)return toast('Rentang tanggal presensi tidak valid.');if(!/^\d{4}\/\d{4}$/.test(f.year)||Number(f.year.slice(5))!==Number(f.year.slice(0,4))+1)return toast('Tahun pelajaran harus berurutan.');}if(mutate(d=>Object.assign(d.settings,f))){render();toast(kind==='school'?'Data sekolah tersimpan.':'Data kelas tersimpan.');}};}

 if($('#student-search'))$('#student-search').oninput=e=>{const pos=e.target.selectionStart;search=e.target.value;render();$('#student-search').focus();$('#student-search').setSelectionRange(pos,pos)};
 if($('#att-chart-period'))$('#att-chart-period').onchange=e=>{attChartPeriod=e.target.value;render()};
 if($('#att-school-days'))$('#att-school-days').onchange=e=>{const value=Number(e.target.value);if(mutate(d=>{d.settings.schoolDays=value})){render();toast('Hari sekolah tersimpan. Hari libur akhir pekan disesuaikan otomatis.')}else e.target.value=String(C.schoolDays(db))};
 if($('#att-date'))$('#att-date').onchange=e=>{if(C.dateValid(e.target.value)){attDate=e.target.value;render()}};
 $$('[data-att]').forEach(el=>el.onchange=()=>{if(C.holiday(db,attDate))return;const old=db.attendance.find(a=>a.studentId===el.dataset.att&&a.date===attDate)?.status||'';if(mutate(d=>{d.attendance=d.attendance.filter(a=>!(a.studentId===el.dataset.att&&a.date===attDate));if(el.value)d.attendance.push({studentId:el.dataset.att,date:attDate,status:el.value})}))render();else el.value=old});
 if($('#grade-subject'))$('#grade-subject').onchange=e=>{gradeSubject=e.target.value;render()};
 if($('#grade-scope'))$('#grade-scope').onchange=e=>{gradeScope=e.target.value;render()};
 $$('[data-score]').forEach(el=>el.onchange=()=>{const a=db.assessments.find(a=>a.id===el.dataset.score),old=a.scores[el.dataset.student],v=el.value;if(v!==''&&(!Number.isFinite(Number(v))||Number(v)<0||Number(v)>100)){el.value=old??'';return toast('Nilai harus antara 0 dan 100.')}const whole=v===''?'':Math.round(Number(v));if(v!==''&&String(whole)!==v)el.value=whole;if(mutate(d=>{const x=d.assessments.find(a=>a.id===el.dataset.score);if(v==='')delete x.scores[el.dataset.student];else x.scores[el.dataset.student]=whole}))$('#avg-'+el.dataset.student).textContent=num(C.mean(gradeList().map(a=>a.scores[el.dataset.student]).filter(v=>typeof v==='number')));else el.value=old??''});
 if($('#journal-month'))$('#journal-month').onchange=e=>{journalMonth=e.target.value;render()};
 if($('#report-student'))$('#report-student').onchange=e=>{reportStudent=e.target.value;render()};
 $$('[data-sig-file]').forEach(inp=>inp.onchange=()=>sigUpload(inp));if($('#sig-transparent'))$('#sig-transparent').onchange=e=>{sigClean=e.target.checked};
 if($('#settings-form'))$('#settings-form').onsubmit=e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.target)),weights={};Object.keys(C.reportTypes).forEach(k=>{weights[k]=Number(f[k]);delete f[k]});f.threshold=Number(f.threshold);if(Object.values(weights).reduce((a,b)=>a+b,0)!==100)return toast('Jumlah bobot harus tepat 100%.');if(mutate(d=>d.settings={...d.settings,...f,weights})){render();toast('Pengaturan tersimpan.')}};
}
function confirmAction(title,message,run,label='Lanjutkan'){close();modal(title,`<p>${message}</p><div class="form-actions">${btn('close','Batal')}${btn('confirmed',label,'primary')}</div>`);$('[data-action="confirmed"]').onclick=()=>{run()}}
function importPreview(next,isRecovery=false){try{C.validate(next)}catch(e){return toast('Cadangan ditolak: '+e.message)}modal(isRecovery?'Pulihkan salinan sebelumnya':'Tinjau berkas JSON',`<p><b>${esc(next.settings.school)}</b><br>Kelas ${esc(next.settings.className)} · ${esc(next.settings.year)} · Semester ${esc(next.settings.semester)}</p><div class="data-summary"><div><b>${next.students.length}</b><small>murid</small></div><div><b>${next.attendance.length}</b><small>presensi</small></div><div><b>${next.assessments.length}</b><small>asesmen</small></div><div><b>${next.journals.length}</b><small>jurnal</small></div></div><div class="notice">Pemulihan mengganti seluruh data aplikasi pada peramban ini. Salinan keadaan sebelumnya akan disimpan otomatis. Unduh cadangan jika ingin menyimpannya sebagai berkas.</div><div class="form-actions">${btn('backup','Unduh data saat ini')}${btn('close','Batal')}${btn('restore-confirm','Ganti & pulihkan','primary')}</div>`);$('[data-action="restore-confirm"]').onclick=()=>{try{const prev=localStorage.getItem(KEY);if(prev)localStorage.setItem(RECOVERY,prev);localStorage.setItem(KEY,JSON.stringify(next));db=next;storageError='';gradeSubject=db.subjects[0]?.id||'';reportStudent='';close();render();toast('Data berhasil dipulihkan.')}catch(e){toast('Pemulihan gagal: ruang penyimpanan tidak tersedia.')}}}
$('#json-file').onchange=async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;if(file.size>20*1024*1024)return toast('Berkas terlalu besar; batas 20 MB.');try{importPreview(JSON.parse(await file.text()))}catch(e){toast('Berkas bukan JSON yang valid: '+e.message)}};
document.addEventListener('click',e=>{
 const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,id=b.dataset.id;
 if(b.closest('form')&&b.type!=='submit')e.preventDefault();
 switch(a){
 case 'close':e.preventDefault();close();break;
 case 'backup':e.preventDefault();backup();break;
 case 'import':$('#json-file').click();break;
 case 'go-school':location.hash='school';break;
 case 'go-attendance':location.hash='attendance';break;
 case 'new-student':studentForm();break;
 case 'edit-student':studentForm(id);break;
 case 'clear-sig':if(mutate(d=>{d.settings[id]=''})){render();toast('Tanda tangan dihapus.')}break;
 case 'archive-student':e.preventDefault();confirmAction('Arsipkan murid?','Murid tidak lagi muncul pada daftar aktif. Presensi dan nilainya tetap tersimpan dan dapat dipulihkan dari arsip.',()=>{if(mutate(d=>d.students.find(x=>x.id===id).active=false)){close();render();toast('Murid diarsipkan.')}},'Arsipkan');break;
 case 'archived':modal('Murid diarsipkan',db.students.filter(s=>s.active===false).map(s=>`<div class="metric-line">${esc(s.name)} ${btn('unarchive','Aktifkan','small',`data-id="${esc(s.id)}"`)}</div>`).join('')||'<p class="sub">Belum ada murid diarsipkan.</p>');break;
 case 'unarchive':if(mutate(d=>d.students.find(s=>s.id===id).active=true)){close();render();toast('Murid aktif kembali.')}break;
 case 'attendance-holidays':attendanceHolidaysDialog();break;
 case 'all-present':if(C.holiday(db,attDate))return toast('Tanggal ini ditandai sebagai hari libur.');if(!C.active(db).length)return toast('Belum ada murid aktif.');if(mutate(d=>{for(const s of C.active(d))if(!d.attendance.some(a=>a.date===attDate&&a.studentId===s.id))d.attendance.push({studentId:s.id,date:attDate,status:'H'})})){render();toast('Status yang kosong diisi hadir.')}break;
 case 'attendance-recap':attendanceRecap();break;
 case 'grade-type':gradeType=id;render();break;
 case 'new-assessment':assessmentForm();break;
 case 'edit-assessment':assessmentForm(id);break;
 case 'delete-assessment':confirmAction('Hapus asesmen?','Seluruh nilai untuk asesmen ini akan terhapus. Unduh cadangan bila masih diperlukan.',()=>{if(mutate(d=>d.assessments=d.assessments.filter(x=>x.id!==id))){close();render();toast('Asesmen dihapus.')}},'Hapus asesmen');break;
 case 'new-journal':journalForm();break;
 case 'edit-journal':journalForm(id);break;
 case 'delete-journal':confirmAction('Hapus jurnal?','Catatan pertemuan ini akan dihapus.',()=>{if(mutate(d=>d.journals=d.journals.filter(x=>x.id!==id))){close();render();toast('Jurnal dihapus.')}},'Hapus jurnal');break;
 case 'clear-journal-filter':journalMonth='';render();break;
 case 'edit-report-notes':reportNotesForm();break;
 case 'new-extracurricular':extracurricularForm(null,id);break;
 case 'edit-extracurricular':extracurricularForm(id);break;
 case 'report-extracurricular':extracurricularForm(null,reportStudent);break;
 case 'delete-extracurricular':confirmAction('Hapus ekstrakurikuler?','Hapus kegiatan ekstrakurikuler ini dari rapor murid pada semester terkait.',()=>{if(mutate(d=>{d.extracurriculars=(d.extracurriculars||[]).filter(r=>r.id!==id)})){close();render();toast('Ekstrakurikuler dihapus.')}},'Hapus');break;
 case 'class-notes':classNotesForm();break;
 case 'print':window.print();break;
 case 'activate-import':confirmAction('Tetapkan periode nilai impor',`Pastikan semua nilai tertunda memang berasal dari tahun ${esc(db.settings.year)}, semester ${esc(db.settings.semester)}. Label sumber adalah tahun lama. Setelah ditetapkan, nilai akan digunakan pada perhitungan semester aktif.`,()=>{if(mutate(d=>{d.assessments.filter(a=>a.period==='review').forEach(a=>a.period=C.period(d));d.importNotes.push('Periode nilai impor ditetapkan guru ke '+C.period(d)+' pada '+today()+'.')})){close();render();toast('Nilai impor masuk ke semester aktif.')}},'Ya, tetapkan periode');break;
 case 'recovery':try{const raw=localStorage.getItem(RECOVERY);if(!raw)return toast('Belum ada salinan sebelum impor.');importPreview(JSON.parse(raw),true)}catch(e){toast('Salinan sebelumnya tidak dapat dibaca.')}break;
 case 'raw-data':download(DocumentNames.make(db,'Data Mentah Ruang Kelas','json',{date:today()}),localStorage.getItem(KEY)||'{}');break;
 case 'subject-up':case 'subject-down':{const from=db.subjects.findIndex(s=>s.id===id),to=from+(b.dataset.action==='subject-up'?-1:1);if(from<0||to<0||to>=db.subjects.length)break;if(mutate(d=>{const [item]=d.subjects.splice(from,1);d.subjects.splice(to,0,item)})){render();const focus=$$('[data-action="'+b.dataset.action+'"]').find(el=>el.dataset.id===id&&!el.disabled)||$$('[data-action="'+(b.dataset.action==='subject-up'?'subject-down':'subject-up')+'"]').find(el=>el.dataset.id===id);focus?.focus();toast('Urutan mata pelajaran tersimpan dan diterapkan ke laporan.')}break}
 case 'delete-subject':{const s=db.subjects.find(x=>x.id===id);if(!s)break;const na=db.assessments.filter(x=>x.subjectId===id).length,nj=db.journals.filter(x=>x.subjectId===id).length,nn=Object.keys(db.reportNotes).filter(k=>k.endsWith('|'+id)).length;
 const parts=[na?na+' asesmen beserta nilainya':'',nj?nj+' jurnal mengajar':'',nn?nn+' catatan rapor':''].filter(Boolean);
 confirmAction('Hapus mata pelajaran?',`<b>${esc(s.name)}</b> akan dihapus dari daftar mapel.`+(parts.length?` Data yang terkait mapel ini ikut terhapus di semua semester: ${parts.join(', ')}.`:' Belum ada data lain yang terkait mapel ini.')+' Tindakan ini tidak dapat dibatalkan; unduh cadangan JSON terlebih dahulu bila perlu.',()=>{if(mutate(d=>{d.subjects=d.subjects.filter(x=>x.id!==id);d.assessments=d.assessments.filter(x=>x.subjectId!==id);d.journals=d.journals.filter(x=>x.subjectId!==id);for(const k of Object.keys(d.reportNotes))if(k.endsWith('|'+id))delete d.reportNotes[k];if(d.journalPlanner){d.journalPlanner.schedule=(d.journalPlanner.schedule||[]).filter(r=>r.subjectId!==id);if(d.journalPlanner.plans)delete d.journalPlanner.plans[id]}})){if(gradeSubject===id)gradeSubject=db.subjects[0]?.id||'';close();render();toast('Mata pelajaran dihapus.')}},'Hapus mapel');break}
  case 'new-subject':case 'rename-subject':{const s=db.subjects.find(s=>s.id===id);modal(s?'Ubah mata pelajaran':'Tambah mata pelajaran',`<form>${input('Nama mata pelajaran *','name',s?.name,'text','required')}<div class="form-actions">${btn('close','Batal','','type="button"')}<button class="primary">Simpan</button></div></form>`,f=>{const name=f.get('name').trim();if(!name||db.subjects.some(x=>x.id!==id&&x.name.toLowerCase()===name.toLowerCase()))return toast('Nama kosong atau sudah digunakan.');if(mutate(d=>{if(s)d.subjects.find(x=>x.id===id).name=name;else d.subjects.push({id:uid('sub'),name})})){close();render();toast('Mata pelajaran tersimpan.')}});break}
 case 'export-students':csv(DocumentNames.make(db,'Data Murid','csv'),[['Nama','NIS','NISN','L/P','Tempat lahir','Tanggal lahir','Agama','Alamat','Ayah','Ibu','Telepon','Status'],...db.students.map(s=>[s.name,s.nis,s.nisn,s.gender,s.birthplace,s.birthdate,s.religion,s.address,s.father,s.mother,s.phone,s.active===false?'Arsip':'Aktif'])]);break;
 case 'export-attendance':csv(DocumentNames.make(db,'Rekap Presensi','csv'),[['Nama','NIS','Mulai','Akhir','Hadir','Sakit','Izin','Tanpa keterangan','Persen hadir'],...db.students.map(s=>{const a=C.attendance(db,s.id);return[s.name,s.nis,db.settings.start,db.settings.end,a.H,a.S,a.I,a.A,a.percent??'']})]);break;
 case 'export-grades':{const list=gradeList();csv(DocumentNames.make(db,'Daftar Nilai - '+subject(gradeSubject),'csv',{gradeRange:gradeScope}),[['Nama','NIS',...list.map(a=>a.tp+' / '+a.label)],...C.active(db).map(s=>[s.name,s.nis,...list.map(a=>a.scores[s.id]??'')])]);break}
 case 'export-journal':csv(DocumentNames.make(db,'Jurnal Mengajar','csv'),[['Tanggal','Mapel','JP','TP','Kegiatan','Refleksi','Tindak lanjut'],...db.journals.filter(j=>j.period===C.period(db)).map(j=>[j.date,subject(j.subjectId),j.jp,j.tp,j.activity,j.reflection,j.followup])]);break;
 case 'export-report':csv(DocumentNames.make(db,'Rekapitulasi Nilai Rapor Semester','csv'),[['Nama','NIS',...db.subjects.map(s=>s.name),'Hadir','Sakit','Izin','Tanpa keterangan'],...C.active(db).map(s=>{const a=C.attendance(db,s.id);return [s.name,s.nis,...db.subjects.map(sub=>C.result(db,s.id,sub.id).value??''),a.H,a.S,a.I,a.A]})]);break;
 }
});
